CREATE TABLE "TB_MKT_DIR_PRED" (
  "MKT_DIR_PRED_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "BASE_DT" DATE NOT NULL,
  "CALC_SEQ" INTEGER NOT NULL,
  "DIR_SCR" INTEGER NOT NULL,
  "UPTREND_RESUME_PROB" INTEGER NOT NULL,
  "BOX_RANGE_PROB" INTEGER NOT NULL,
  "RE_CORRECTION_PROB" INTEGER NOT NULL,
  "RETEST_LOW_PROB" INTEGER NOT NULL,
  "UPTREND_RESUME_CHG" INTEGER NOT NULL DEFAULT 0,
  "BOX_RANGE_CHG" INTEGER NOT NULL DEFAULT 0,
  "RE_CORRECTION_CHG" INTEGER NOT NULL DEFAULT 0,
  "RETEST_LOW_CHG" INTEGER NOT NULL DEFAULT 0,
  "INPUT_BASE_DT_JSON" JSONB NOT NULL,
  "CALC_BASIS_JSON" JSONB NOT NULL,
  "RULE_VER_NO" INTEGER NOT NULL DEFAULT 1,
  "LATEST_YN" CHAR(1) NOT NULL DEFAULT 'Y',
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_MKT_DIR_PRED_01" UNIQUE ("BASE_DT", "CALC_SEQ"),
  CONSTRAINT "CK_TB_MKT_DIR_PRED_01" CHECK ("DIR_SCR" BETWEEN 0 AND 100),
  CONSTRAINT "CK_TB_MKT_DIR_PRED_02" CHECK (
    "UPTREND_RESUME_PROB" BETWEEN 0 AND 100 AND "BOX_RANGE_PROB" BETWEEN 0 AND 100
    AND "RE_CORRECTION_PROB" BETWEEN 0 AND 100 AND "RETEST_LOW_PROB" BETWEEN 0 AND 100),
  CONSTRAINT "CK_TB_MKT_DIR_PRED_03" CHECK (
    "UPTREND_RESUME_PROB" + "BOX_RANGE_PROB" + "RE_CORRECTION_PROB" + "RETEST_LOW_PROB" = 100),
  CONSTRAINT "CK_TB_MKT_DIR_PRED_04" CHECK ("LATEST_YN" IN ('Y','N'))
);
CREATE UNIQUE INDEX "UK_TB_MKT_DIR_PRED_LATEST" ON "TB_MKT_DIR_PRED" ("BASE_DT") WHERE "LATEST_YN"='Y';
CREATE INDEX "IDX_TB_MKT_DIR_PRED_01" ON "TB_MKT_DIR_PRED" ("BASE_DT" DESC);

ALTER TABLE "TB_BRF"
  ADD COLUMN "MKT_RISK_SCR" INTEGER,
  ADD COLUMN "MKT_RISK_GRADE" VARCHAR(20),
  ADD COLUMN "MKT_PHASE" VARCHAR(30),
  ADD COLUMN "MKT_DIR_PRED_ID" BIGINT,
  ADD COLUMN "MKT_DIR_SCR" INTEGER,
  ADD COLUMN "REG_BUY_SIG" VARCHAR(30),
  ADD COLUMN "DAILY_ACT_SIG" VARCHAR(30),
  ADD COLUMN "RCMD_CASH_RT" INTEGER,
  ADD COLUMN "SOURCE_FIX_DTTM" TIMESTAMPTZ,
  ADD CONSTRAINT "FK_TB_BRF_05" FOREIGN KEY ("MKT_DIR_PRED_ID") REFERENCES "TB_MKT_DIR_PRED"("MKT_DIR_PRED_ID"),
  ADD CONSTRAINT "CK_TB_BRF_10" CHECK ("MKT_RISK_SCR" IS NULL OR "MKT_RISK_SCR" BETWEEN 0 AND 100),
  ADD CONSTRAINT "CK_TB_BRF_11" CHECK ("MKT_DIR_SCR" IS NULL OR "MKT_DIR_SCR" BETWEEN 0 AND 100),
  ADD CONSTRAINT "CK_TB_BRF_12" CHECK ("RCMD_CASH_RT" IS NULL OR "RCMD_CASH_RT" BETWEEN 0 AND 100);

COMMENT ON TABLE "TB_MKT_DIR_PRED" IS 'DB에서 확정한 1~4주 시장방향 시나리오 예측';
COMMENT ON COLUMN "TB_MKT_DIR_PRED"."INPUT_BASE_DT_JSON" IS '계산 입력별 원천데이터 기준일';
COMMENT ON COLUMN "TB_BRF"."SOURCE_FIX_DTTM" IS 'OpenAI 호출 전 브리핑 Snapshot 확정시각';
